/* Propuestas resumidas de los planes escaneados del CNE (OCR + lectura, Tinta Digital) */
(function(){
const P=window.PROP=window.PROP||{};
P.riobamba=Object.assign(P.riobamba||{},{"FALCONI": ["Un sistema municipal de prevención con iluminación focalizada, cámaras y alarmas comunitarias, coordinado con Policía y ECU 911, más rutas seguras y accesibilidad para mujeres, adultos mayores y personas con discapacidad. Refuerza al Cuerpo de Bomberos. Sin cifras ni presupuesto.", "Plan de recuperación vial jerarquizado (bacheo, recapeo, adoquinado) coordinado con las redes de agua, modernizar rutas, frecuencias y tecnología del transporte público, red peatonal y ciclista segura, y gestionar la Nueva Circunvalación con el MTOP y la Prefectura. Bacheo desde el año 1; vías en las 11 parroquias rurales en 2029.", "Programa “Riobamba Agua Segura”: sectorización, telemetría y control de fugas desde el primer año; Plan Cantonal de Alcantarillado con soluciones descentralizadas en lo rural; gestión técnica de la PTAR y monitoreo del río Chibunga. Sin propuesta específica de drenaje pluvial.", "Plan de gestión integral de residuos con separación en origen, recolección diferenciada y reciclaje inclusivo formalizado; fortalecer la planta de compostaje de Porlón; programa “Ríos Vivos” para riberas y quebradas. En riesgos: control de construcciones, alertas y Bomberos, solo en general."], "JARA": ["“Barrios Seguros, Familias Tranquilas”: sistemas de seguridad por sector, recuperación de espacios públicos y prevención comunitaria con Policía y ECU 911, más programas contra el reclutamiento de niños y adolescentes por el crimen organizado y contra el trabajo infantil. Sin cifras ni presupuesto.", "“Movilidad Inteligente”: mejorar vías y ciclovías, modernizar el transporte público y sus paradas, y sistemas inteligentes de tránsito, medidos en kilómetros intervenidos. Sin obras con nombre ni metas numéricas.", "Mejorar los sistemas de agua potable y alcantarillado, drenaje pluvial y control de calidad del agua, con financiamiento del BEDE y trabajo con las juntas de agua. Sin plantas ni meta de cobertura.", "Reforestación urbana y rural, recuperar quebradas y riberas y proteger fuentes de agua; gestión integral de residuos con reciclaje inclusivo, eficiencia energética y educación ambiental, bajo el eje “Resiliencia Climática y Economía Circular”. Riesgos solo vía coordinación con Gestión de Riesgos."], "VINUEZA": ["La seguridad va dentro del eje “Cuidar de la gente”: una ciudad interconectada con una red de bulevares seguros, consolidar los Puntos Seguros, prevención y convivencia, y un sistema territorial del cuidado con las Casas de Bienestar (con UNICEF). Es continuidad de la gestión 2023-2027; no fija cámaras ni cifras nuevas.", "Un “Sistema Inteligente de Movilidad”: nuevas soluciones de transporte público, pasos a desnivel en los principales accesos de la ciudad, modernización del transporte, movilidad activa (caminabilidad, ciclovías, corredores urbanos) y tecnología para gestionar el tránsito. Sin plazos ni montos.", "“Soberanía hídrica”: proteger las fuentes y ejecutar el Proyecto Maguazo-Alao como infraestructura estratégica de abastecimiento, captación, almacenamiento y recarga, más drenaje urbano sostenible. No detalla alcantarillado ni plantas de tratamiento.", "Infraestructura verde-azul (páramos, humedales, corredores), recuperar las cuencas de los ríos Chibunga y Chambo, el río Chibunga como gran corredor ambiental, economía circular con “La Basura, el Mejor Negocio de Riobamba”, nueva flota y Complejo Ambiental. En riesgos: alertas tempranas, microzonificación sísmica, control de inundaciones y COE cantonal."], "DAQUI": ["“Territorios Vivos”: un Plan Cantonal de Seguridad participativo, corredores seguros escolares, universitarios y comerciales con iluminación y señalización, un Centro Vivo con mercados ordenados, brigadas territoriales de mantenimiento y acuerdos comunitarios de cuidado. Metas medidas en porcentajes de avance, sin cifras ni presupuesto.", "Reestructurar rutas, frecuencias y paradas del transporte público con estudios origen-destino, potenciar los accesos a la ciudad (salidas a Quito, Licán, Chambo, Guamote, Guano y Penipe) con MTOP y Prefectura, repavimentar vías estratégicas con drenaje e iluminación, semaforización según flujo y una red peatonal y ciclista conectada.", "“Agua Segura y Continua”: actualizar el Plan Maestro, sectorizar redes, bajar el agua no contabilizada con macro y micromedición, control de calidad desde la captación, expansión planificada al borde periurbano y reservas ante sequías. “Alcantarillado Seguro”: nuevo plan maestro, redes en sectores no atendidos, rehabilitar colectores y separar aguas lluvias de residuales.", "“Riobamba Circular y Limpia”: recolección diferenciada, separación en barrios y mercados, compostaje de orgánicos, reciclaje inclusivo, control de botaderos y disposición final segura. Proteger las fuentes de captación con acuerdos de conservación y restauración de páramos, recuperar el Chibunga; “Riobamba Preparada” con mapas multiamenaza, puntos críticos de inundación y riesgo en toda obra municipal."], "ALDAS": ["“Riobamba Segura” (USD 5-8 millones de referencia): prevención situacional con mapas de puntos críticos, iluminación, cámaras interoperables con protocolos, botones o canales de alerta donde sean viables y mesas con Policía, ECU 911 y comunidades. El plan advierte que el Municipio no investiga delitos y medirá cobertura preventiva, no “delitos resueltos”.", "“Bacheo 48H” como piloto inmediato con protocolo verificable en las cinco parroquias urbanas (USD 4-6 M), “Riobamba Vías” para corredores con diagnóstico de estructura y drenaje (USD 22-34 M), “Movilidad Inteligente” con semaforización coordinada y gestión multimodal (USD 7-12 M) y “Riobamba Accesible”. Vialidad rural solo por convenio con la Prefectura.", "“Riobamba Agua” (USD 18-28 M, estudios y fases): continuidad y calidad en redes priorizadas como Saboya, San José de Tapi y San Martín de Veranillo, más sistemas rurales; “Riobamba Separa” (USD 22-42 M, prefactibilidad) para separar aguas lluvias y residuales en el centro-sur y reducir descargas; “Saneamiento Rural Digno”.", "“Riobamba Limpia” (USD 8-14 M): separación en origen, rutas diferenciadas, formalizar recicladores, control de grandes generadores y disposición final segura, medido con pesaje y GPS. “Riesgos y Resiliencia” (USD 6-10 M) para drenaje y adaptación climática. Todos los montos son rangos referenciales, no presupuesto."]});
P.ambato=Object.assign(P.ambato||{},{"CAIZA": ["No tiene un eje propio de seguridad ciudadana: habla de acciones para mejorar la movilidad y la seguridad vial, y de programas de prevención y atención de violencia intrafamiliar y de género. Sin cámaras, guardia municipal ni cifras.", "Una meta de subir 20% la cobertura y calidad de servicios, movilidad e infraestructura vial urbana y rural, medida en kilómetros de vías construidas. Sin obras, rutas ni transporte público concretos.", "Reconoce que no hay agua potable en la zona rural y promete ampliar los servicios básicos dentro de esa misma meta del 20%. Sin plantas, redes ni plazos específicos.", "Reforestar y recuperar áreas degradadas (hectáreas por año), subir 25% los indicadores de calidad ambiental con recolección diferenciada, reciclaje y educación ambiental, y crear parques y corredores verdes. En riesgos solo menciona zonas de riesgo en urbanizaciones."], "AMOROSO": ["Convenio con el Ministerio del Interior y la Policía, reformar la ordenanza de seguridad y activar “Comités de Seguridad Barrial”, videovigilancia inteligente y alarmas comunitarias (incluidas parroquias rurales), un Plan Maestro de Iluminación LED en ejes comerciales y “Empleo Joven por la Paz” para jóvenes de 15 a 24 años. Todo de 2027 a 2031.", "Ordenanza de Plan Vial Urbano jerarquizado, un sistema georreferenciado de activos viales, mantener las vías entre plataformas, racionalizar rutas y frecuencias de buses, al menos un carril exclusivo para transporte público, un Sistema de Información de Transporte y regeneración de aceras, rampas e iluminación peatonal desde el centro histórico.", "El agua entra por el saneamiento: ampliar la red a sectores rurales, modernizar las plantas de aguas residuales para depurar el río Ambato, reducir 40% los vertidos directos, monitoreo en línea en 5 puntos y reúso de aguas tratadas. Sobre agua potable solo menciona la competencia, sin obras.", "Recolección diferenciada en el 100% de hogares, planta de clasificación y compostaje (15 t/mes), puntos limpios en 15 sectores, proteger los páramos sobre los 3.300 msnm, reforestar zonas de recarga y corredores biológicos. En riesgos: mapas actualizados, alerta temprana con 10 estaciones, líderes capacitados y simulacros anuales."], "SALAZAR": ["Eje “Ambato Seguro y Conviviente”: recuperar espacios públicos y mejorar iluminación, fortalecer la videovigilancia municipal en coordinación con las autoridades y un programa “Barrios organizados”. Las metas se definirán cada año en el POA: no hay cifras ni presupuesto.", "Un Plan Integral de Movilidad Ambato 2031, programa de mantenimiento vial urbano (km intervenidos), intervención de puntos críticos con señalización y semaforización, y un sistema de movilidad accesible. Sin transporte público, obras ni rutas con nombre.", "“Ambato con agua segura” (fortalecer infraestructura y gestión a través de la entidad competente) y un Plan Cantonal de Saneamiento que amplíe redes “según planificación y presupuesto”. Sin plantas, captaciones ni metas de cobertura.", "Gestión integral de residuos (toneladas aprovechadas), “Ambato limpio” en puntos críticos, recuperar áreas verdes, proteger quebradas y arborizar la ciudad. En riesgos: un Sistema Cantonal de Gestión de Riesgos e intervenciones preventivas en zonas vulnerables, sin obras concretas."], "NARANJO": ["Iluminación, recuperación de espacios públicos, videovigilancia estratégica, alarmas comunitarias y participación barrial, en coordinación con las entidades competentes, dentro del eje “Ambateñidad”. Es un plan de 7 páginas: sin cifras, presupuesto ni plazos.", "Reorganización vial, conectividad parroquial, movilidad peatonal, ciclovías y mejora del transporte “sobre la base de estudios”. Como obras emblemáticas: una solución vial integral en El Socavón (paso deprimido o puente, por definir) y otra en la Manzana de Oro, ambas condicionadas a estudios y financiamiento.", "Una línea: mejorar calidad, cobertura y agilidad del agua potable y el alcantarillado, con modernización y digitalización de trámites. Sin plantas, redes ni metas.", "Parques, jardines y una ciudad “limpia, verde, iluminada”, con protección de zonas estratégicas en el ordenamiento territorial. No tiene propuestas específicas de residuos, reforestación ni gestión de riesgos."], "ALTAMIRANO": ["“Ambato Seguro”: convertir la Sala de Monitoreo Municipal en un Sistema Inteligente de Seguridad Urbana con inteligencia artificial, analítica de video y lectura automática de placas, fortalecer a los agentes de control municipal, y recuperar espacios con iluminación y parques. Como anclas sociales, el Teatro de la Ciudad y el Centro Cultural Casigana. Sin cifras de cámaras ni presupuesto.", "Plan Emergente de Recapeo Vial y mantenimiento de la red cantonal como prioridad inmediata, una solución de ingeniería para el nodo del Redondel de la Policía, implementar el PMUS con transporte público fortalecido, semaforización inteligente, bulevares, ciclovías y soterramiento de redes en el centro.", "El agua se aborda desde la fuente: proteger páramos, zonas de recarga y microcuencas con un Cinturón Ecológico Andino y acuerdos de conservación con juntas de agua. El diagnóstico alerta de un “inminente desabastecimiento”, pero no hay obras de agua potable ni alcantarillado con nombre.", "Plan de Recuperación Ecológica del río Ambato y sus quebradas, reforestación nativa, corredores ecológicos y parques lineales para reducir inundaciones, más arbolado urbano, drenaje y soluciones basadas en la naturaleza. Economía circular y gestión de residuos solo en general."]});
P.loja=Object.assign(P.loja||{},{"CARRION": ["Promete espacios públicos seguros y accesibles, mejor alumbrado público (en coordinación con otras entidades) y proyectos de movilidad y seguridad vial. No hay guardia, cámaras, alarmas ni cifras: es una lista de lineamientos generales.", "Rehabilitar y mantener la vialidad urbana municipal, coordinar con otras entidades la vialidad rural y los caminos vecinales, y construir aceras, bordillos y obras de accesibilidad. Sin transporte público, terminal ni obras con nombre.", "Mejorar y ampliar los sistemas de agua potable y saneamiento “de acuerdo con las competencias” y apoyar proyectos de riego. Sin plantas, captaciones, metas ni plazos.", "Proteger fuentes hídricas y microcuencas, reforestación permanente, fortalecer la gestión de residuos sólidos, educación ambiental y prácticas agroecológicas. Riesgos: acciones de prevención, mitigación y respuesta, en general."], "VALDIVIESO": ["“Loja Violeta”: espacios públicos seguros e inclusivos, regeneración de 20 barrios con mejor infraestructura, iluminación y seguridad, escalinatas recuperadas como puntos de encuentro y políticas de protección a la mujer y la familia. No propone cámaras, guardia ni cifras de seguridad.", "Un plan maestro de movilidad sostenible e inteligente, una ordenanza para modernizar el transporte, transporte alternativo, sistemas inteligentes de tránsito contra la siniestralidad, Plan Vial de barrios, Plan Emergente de Vialidad Rural y equipar a los obreros para bacheo inmediato.", "“Loja Azul”: agua de calidad las 24 horas, repotenciar los sistemas urbanos y rurales, una nueva planta potabilizadora en Jipiro, fortalecer la empresa de agua y alcantarillado, ampliar el alcantarillado sanitario y pluvial e interceptar y tratar las descargas que hoy van a ríos y quebradas.", "“Loja Verde”: un millón de árboles nativos, reforestar el Villonaco y Ventanas, corredores ecológicos, rediseñar la gestión de desechos sólidos y un censo y normativa de fauna urbana. En riesgos: planes de estabilización geomorfológica y un Centro Integral de Gestión de Riesgos y Respuesta Climática."]});
P.ibarra=Object.assign(P.ibarra||{},{"CABEZAS": ["Eje 1 del plan: prevención comunitaria, mediación y cultura de paz, recuperar parques y plazas con mejor iluminación, coordinación con las instituciones de seguridad y “herramientas tecnológicas” dentro de las competencias municipales. Sin cámaras, guardia ni cifras: son políticas y líneas de acción, no obras.", "Mantener, rehabilitar y mejorar progresivamente la infraestructura vial, proyectos de conectividad urbana y rural con seguridad vial y accesibilidad universal, y recuperar espacios públicos. No nombra transporte público, terminal ni obras concretas.", "Fortalecer progresivamente la infraestructura y gestión de los sistemas de agua potable y saneamiento, proteger fuentes y zonas de recarga y trabajar con las juntas de agua. Sin plantas, cobertura meta ni drenaje pluvial.", "Conservar microcuencas y páramos, reforestación y restauración ecológica, educación ambiental, reciclaje y economía circular. En riesgos: estudios técnicos, monitoreo y acciones preventivas, con el cambio climático como criterio transversal. Todo en términos generales."], "MONCAYO": ["“Escudo Ibarra”: una central C4 municipal, 400 cámaras con inteligencia artificial y alarmas comunitarias conectadas al ECU 911 en el 100% de barrios (USD 5 millones, con tasa de seguridad y convenio con el Ministerio del Interior), más 60 parques iluminados con LED y escuelas de paz y mediación en 30 barrios vulnerables.", "Plan Maestro de Vialidad y Movilidad por USD 38 millones: 80 km de vías urbanas y caminos rurales pavimentados, 25 cruces semafóricos inteligentes, reingeniería de rutas y frecuencias de buses, integración tarifaria y red de ciclovías seguras. Financiado con contribución de mejoras y crédito del BDE.", "Agua potable y saneamiento al 98% de cobertura, con énfasis en saneamiento rural y regeneración del Centro Histórico (USD 24 millones con EMAPA-I y crédito BDE). Plan Yahuarcocha 2031: suprimir el 100% de descargas a la laguna y construir una planta depuradora (USD 12 millones).", "“Ibarra Verde y Circular”: 100.000 árboles nativos plantados y 35% de residuos reciclados en origen. “Agua, Quebradas y Cantón Resiliente”: 25 km de quebradas protegidas y sistemas de alerta temprana en las 7 parroquias rurales (USD 10 millones con SNGRE). Plan total de inversión: USD 164 millones."], "POSSO": ["“Ibarra se cuida”: fortalecer la Unidad y el Consejo de Seguridad, invertir en UPC y tecnología preventiva (alarmas, cámaras y botones de pánico) para complementar al Gobierno, prevención del consumo de alcohol y drogas en jóvenes y sistemas contra el acoso sexual en el transporte. Sin cifras ni presupuesto.", "Mejora integral del transporte público urbano y rural con enfoque de género y accesibilidad, una pirámide vial que prioriza peatones, ciclistas y buses antes que autos, mejorar el terminal de interconexión, proyecto de ciclovías y transición de taxis, camiones y motos a energías limpias.", "El agua aparece en el eje de bienestar: mejorar el acceso a agua potable y la gestión de desechos “para prevenir enfermedades”, y gestionar estudios y financiamiento para proyectos de agua. No hay plantas, redes ni metas de cobertura.", "Rehabilitar quebradas como biocorredores, política de ciudad verde con las tres R, basura cero, forestación urbana y rural y remediar ambientalmente los rellenos sanitarios. En riesgos: sistema de información, monitoreo continuo y programas barriales de prevención y capacitación."]});
P.latacunga=Object.assign(P.latacunga||{},{"ITURRALDE": ["Gestionar ante el Gobierno más presencia policial y unidades especializadas, un Centro de Monitoreo y Coordinación de Emergencias local articulado al ECU 911, mapas de riesgo para pasar “de la videovigilancia a la acción”, el programa barrial “Conociendo a mi vecino” y compensaciones para las comunidades vecinas al Centro de Privación de Libertad. Diagnóstico en 2027, ejecución desde 2028.", "Evaluación integral del sistema de movilidad, revisar y sincronizar semáforos en corredores estratégicos, un programa permanente de mantenimiento vial (bacheo, pavimentación, adoquinado) y estudiar una planta municipal de asfalto, ciclovías y ciclo-parqueaderos, estudios para modernizar el Terminal Terrestre y polos comerciales en el norte y sur para descongestionar el Centro Histórico.", "“Agua para Todos”: evaluación técnica de todo el sistema, nuevas captaciones, un plan para proteger las fuentes ante una erupción volcánica, modernizar las plantas de Alcoceres, El Calzado e Ishigua, mejorar presión en sectores altos, ampliar redes rurales y reducir pérdidas. En saneamiento: más alcantarillado sanitario y pluvial en zonas que se inundan en invierno y optimizar las plantas de tratamiento.", "“Latacunga Recicla”: recolección diferenciada, infraestructura de separación, evaluar una planta de reciclaje municipal o intermunicipal y alianzas con recicladores. “Latacunga Verde”: vivero municipal, reforestación urbana y rural y un Jardín Botánico en Belisario Quevedo (sujeto a estudios). Riesgos: priorizar zonas de inundación en saneamiento y el riesgo volcánico en agua."], "GUAMAN": ["La seguridad aparece dentro de la regeneración urbana: parques, plazas y espacios públicos con iluminación, seguridad y accesibilidad. No hay un programa propio de seguridad ciudadana, cámaras ni coordinación con la Policía. El plan traslada los proyectos del PDOT 2024-2040 a compromisos de gestión.", "Un Programa Integral de Movilidad Urbana Sostenible: ordenamiento del tránsito, seguridad vial, transporte público eficiente, infraestructura peatonal y mejor conectividad, con criterios ambientales y de accesibilidad. Sin obras, rutas ni plazos.", "Continuar el Plan Maestro de Agua y Alcantarillado Urbano priorizando sectores con déficit, y un Plan de Reducción de Brechas rural que amplíe los sistemas comunitarios en parroquias con menor cobertura. Sin plantas ni cifras.", "Conservar páramos y humedales, recuperar el río Cutuchi y sus riberas, un Complejo Ambiental para gestión integral de residuos con reciclaje y valorización, y un Sistema Cantonal de Riesgos y Alerta Temprana ante amenazas volcánicas, inundaciones e incendios, incluida la protección del patrimonio frente a lahares."], "TERAN": ["“Latacunga Segura e Inteligente”, por años: en 2027 diseñar el Sistema Municipal de Seguridad Inteligente; en 2028 cámaras en accesos, mercados, parques, terminales y zonas escolares; en 2029 lectura automática de placas y analítica de video con IA; en 2030 integrar cámaras municipales y comunitarias. Suma botones de pánico, programa “Latacunga Iluminada y Vigilada” y criterios CPTED en espacios públicos.", "Plan Maestro de Reordenamiento del Transporte Público en el año 2, una Red de Micro-Movilidad Segura y peatonalización inclusiva en el año 3, y semaforización inteligente y adaptativa (“Smart Traffic”) con IA desde el año 1, más una plataforma para reportar baches y fallas. Sin obras viales con nombre.", "“Latacunga cero fugas”: sectorización hidráulica, macromedidores y un Centro Municipal de Detección de Fugas en el año 1, sensores IoT y reparaciones en menos de 24 horas, renovación de tuberías críticas en el año 4, nuevos tanques, asistencia a juntas de agua rurales y un Centro Inteligente de Gestión del Agua con app ciudadana. En saneamiento: colectores prioritarios y tratamiento progresivo de aguas residuales.", "Plan Cantonal “Latacunga Verde” con inventario ambiental y reforestación, Estrategia Municipal de Economía Circular y Reciclaje en los años 3 y 4, y “Latacunga Resiliente”: mapas de riesgo actualizados, sistema comunitario de gestión del riesgo con simulacros parroquiales ante el Cotopaxi, y una plataforma de monitoreo y alertas tempranas en el año 3."]});
P.zamora=Object.assign(P.zamora||{},{"SIMBANA": ["No hay un eje de seguridad ciudadana: el plan habla de “entornos seguros, inclusivos y accesibles” en parques y espacios públicos, y de seguridad vial. Sin cámaras, guardia municipal ni coordinación con la Policía. Es un plan de 6 páginas, sin cifras.", "Mantener y mejorar la vialidad urbana, señalización, equipamiento urbano y “sistemas de movilidad sostenible”, y rehabilitar la infraestructura municipal. Sin obras ni rutas concretas.", "Ampliar y mejorar la cobertura, calidad y sostenibilidad del agua potable, el alcantarillado y el saneamiento para la zona urbana y rural, y gestionar proyectos estratégicos con el Gobierno, la Prefectura, la SCTEA y la cooperación internacional. Sin plantas ni metas.", "Proteger cuencas hidrográficas, áreas de conservación y espacios verdes, educación ambiental y economía circular, gestión integral de residuos sólidos. En riesgos: prevención, mitigación y capacidad de respuesta ante amenazas naturales y antrópicas, en general."], "CABRERA": ["Un proyecto nuevo del candidato: fortalecer la seguridad ciudadana y la gestión de riesgos con videovigilancia y alerta temprana en espacios públicos y zonas de deslizamientos y desborde de ríos (prioridad alta). El plan aclara que no compromete “obras, montos ni ubicaciones” en esta fase.", "Vialidad y mantenimiento vial urbano-rural como proyecto de prioridad alta (incluidas cabeceras parroquiales), un instrumento cantonal de movilidad, tránsito y transporte, y gestionar ante el Gobierno el mantenimiento de la Troncal Amazónica. Sin rutas ni transporte público concretos.", "Ampliación de agua potable y alcantarillado en zonas urbanas y rurales dentro del Programa de servicios básicos (prioridad alta) y gestión integral de aguas servidas y saneamiento. Sin plantas, captaciones ni cifras.", "Gestión integral de desechos sólidos, protección de fuentes hídricas y cuencas con la Prefectura y el MAATE, y fortalecer la gestión de riesgos y la adaptación climática ante inundaciones. Suma espacios recreativos como el parque Santa Elena y el mirador del Reloj de Zamora."]});
P.galapagos=Object.assign(P.galapagos||{},{"OCHOA": ["La seguridad entra solo por el espacio público: mejorar la iluminación de parques, plazas y malecones “para fortalecer la seguridad ciudadana” y mobiliario accesible. No hay cámaras, guardia, alarmas ni coordinación con la Policía.", "Programas permanentes de mantenimiento de vías urbanas y rurales priorizadas con criterios técnicos, rehabilitar aceras, bordillos y drenaje pluvial, y accesibilidad universal. No habla de transporte público ni de movilidad insular (bicicletas, taxis, muelles).", "Diagnóstico integral del sistema de agua potable para detectar pérdidas, estudios para nuevas captaciones y almacenamiento, rehabilitar redes por sectores, monitoreo de calidad y tecnología de control. En saneamiento: mantenimiento de la red, ampliaciones y proyectos de tratamiento de aguas residuales para proteger ecosistemas terrestres y marinos.", "Mejor recolección, más puntos de reciclaje en espacios públicos, educación ambiental y alianzas para valorizar reciclables; un nuevo Centro Municipal de Faenamiento con tratamiento de efluentes. En riesgos: actualizar planes de prevención y respuesta y acciones ante el cambio climático, sin obras concretas."], "CAIZA": ["El plan reconoce que la seguridad no es competencia municipal y se limita a “gestionar ante los distintos niveles de gobierno” obras y servicios de salud, educación y seguridad. No hay cámaras, alarmas ni programas de prevención propios.", "Una sola línea de acción: regeneración urbana y mejoramiento de la vialidad y accesibilidad urbana y rural, articulada con el MTOP y el CGREG. El diagnóstico menciona la dependencia del transporte marítimo y aéreo, pero no hay propuesta sobre ello.", "Mejorar la infraestructura y fortalecer el modelo de gestión del sistema de agua potable de San Cristóbal, en coordinación con el MAATE, el CGREG, la Empresa Pública de Agua y entidades de financiamiento. Sin cifras ni alcantarillado específico.", "Repotenciar el centro de tratamiento de residuos sólidos con economía circular (con MAATE y CGREG) y más espacios públicos y deportivos. No tiene propuestas de reforestación ni de gestión de riesgos; el diagnóstico apunta a la transición energética y a las especies invasoras, sin convertirlas en acciones."]});
P.machala=Object.assign(P.machala||{},{"PEREIRA": ["Plan “Machala Segura” en dos fases: en el año 1, pórticos de videovigilancia con lectura de placas en los accesos al cantón y capacitación de los agentes de control municipal; en los años 2 y 3, corredores seguros con cámaras de reconocimiento facial y drones con IA, conectados con la ciudadanía en zonas comerciales y educativas. Suma parques con luz LED e internet gratis en la periferia.", "Plan Maestro de asfaltado y pavimentación barrial en el año 1, buses eléctricos para el transporte urbano, cambio de las tarjetas de estacionamiento a un sistema rotativo tarifado y, en el año 4, un Sistema Integrado de Movilidad con rutas reestructuradas, paradas inteligentes y ejes no motorizados.", "Buscar financiamiento para reemplazar toda la tubería de asbesto-cemento que sale de la planta La Esperanza, separar alcantarillado pluvial y sanitario en cada regeneración urbana y, en los años 2 y 3, ampliar redes matrices y construir colectores pluviales para eliminar los puntos de anegamiento.", "En el año 1, limpieza de emergencia de los esteros El Macho y Huaylá y canales de drenaje contra inundaciones; luego separación en la fuente y reciclaje inclusivo, “Machala Verde” para subir los m² de área verde por habitante, y en el año 4 el cierre técnico del botadero y un Complejo Ambiental con compostaje o aprovechamiento energético."]});
const S=window.SCAN||{};for(const c in P){if(S[c])S[c]=S[c].filter(k=>!P[c][k]);}
})();

(function(){const P=window.PROP;P.machala=Object.assign(P.machala||{},{"IZQUIERDO": ["“Plan Machala Segura y en Convivencia”: Sistema Municipal Integrado de Videovigilancia y Alerta Comunitaria (cámaras, botones de auxilio y mapas de riesgo articulados al ECU 911), “Machala Iluminada y Segura” con luminarias en parques, canchas y zonas escolares, corredores seguros y un proyecto “Puerto Bolívar Seguro”. Sin cifras ni presupuesto.", "“Machala se Mueve”: Plan Maestro de Movilidad Urbana Sostenible, semáforos adaptativos y un centro de control de tránsito, cruces seguros en zonas escolares y hospitalarias, red de parqueaderos municipales, revisión de paradas y rutas, un paso elevado en el acceso principal a Machala y repotenciar la Circunvalación Sur, por etapas.", "El agua entra por el drenaje: “Machala libre de inundaciones graves”, con limpieza programada de sumideros y canales antes del invierno, inventario georreferenciado de anegamientos, más colectores y estaciones de bombeo, la primera etapa de la intervención integral del Estero El Macho y un sistema cantonal de monitoreo de lluvias. No hay metas específicas de agua potable.", "“Machala Limpia 365”: optimizar rutas y limpieza de mercados, georreferenciar y sancionar botaderos clandestinos, atención diferenciada a El Retiro, “Recicla Machala” con separación en origen e industrialización de residuos, arborización “Machala Verde 2031” y barrios permeables con jardines de lluvia. Riesgos: alerta temprana y criterios climáticos en toda obra pública."]});window.SCAN.machala=[];})();

